<?php
/**
 * Plugin Name: NESPORTS3 Updater V41 (Store Products & Price Manager)
 * Description: Adds live Product & Price Manager in WordPress Admin: Add Product, Delete Product, Quick Price Update.
 * Version: 41.0
 * Author: NESports
 */

if (!defined('ABSPATH')) exit;

function run_nesports_v41_update() {
    $target_dirs = array(
        WP_PLUGIN_DIR . '/nesports-pro',
        WP_PLUGIN_DIR . '/nesports-pro-store',
        WP_PLUGIN_DIR . '/nesports-custom'
    );
    if (is_dir(WP_PLUGIN_DIR)) {
        $files = scandir(WP_PLUGIN_DIR);
        foreach ($files as $f) {
            if ($f === '.' || $f === '..') continue;
            if (strpos($f, 'nesports-pro') === 0) {
                $full = WP_PLUGIN_DIR . '/' . $f;
                if (is_dir($full) && !in_array($full, $target_dirs)) {
                    $target_dirs[] = $full;
                }
            }
        }
    }
    
    $payloads = array(
        'includes/class-nesports-admin.php' => base64_decode(''),
        'includes/helpers.php' => base64_decode(''),
        'templates/sections/section-collections-carousel.php' => base64_decode(''),
        'templates/page-home.php' => base64_decode(''),
        'templates/header-nesports.php' => base64_decode(''),
        'assets/css/nesports-frontend.css' => base64_decode(''),

    );
    
    $results = array();
    foreach ($target_dirs as $td) {
        if (!is_dir($td)) continue;
        $results[$td] = array();
        foreach ($payloads as $rel => $data) {
            $dest = $td . '/' . $rel;
            $d = dirname($dest);
            if (!is_dir($d)) {
                if (function_exists('wp_mkdir_p')) {
                    wp_mkdir_p($d);
                } else {
                    @mkdir($d, 0755, true);
                }
            }
            $w = file_put_contents($dest, $data);
            $results[$td][$rel] = ($w !== false) ? "SUCCESS ($w bytes)" : "ERROR";
        }
    }

    // Auto-seed managed catalog in wp_options if not exists
    $managed = get_option('nesports_managed_catalog', null);
    if ($managed === null || !is_array($managed) || empty($managed)) {
        if (function_exists('nesports_preset_catalog')) {
            $preset = nesports_preset_catalog();
            update_option('nesports_managed_catalog', $preset);
            $results['managed_catalog_init'] = "INITIALIZED with " . count($preset) . " products";
        }
    } else {
        $results['managed_catalog_init'] = "ALREADY_EXISTS with " . count($managed) . " products";
    }

    if (class_exists('\Elementor\Plugin')) {
        \Elementor\Plugin::$instance->files_manager->clear_cache();
    }

    return $results;
}

add_action('init', function() {
    if (isset($_GET['nesports_apply_v41']) && $_GET['nesports_apply_v41'] === '1') {
        $res = run_nesports_v41_update();
        header('Content-Type: application/json');
        echo json_encode(array('status' => 'ok', 'results' => $res));
        exit;
    }
});

register_activation_hook(__FILE__, function() {
    run_nesports_v41_update();
});
